"""Snap clock times to a step and label the results."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span

def _check_step(step_minutes: int) -> None:
    """A step must be positive and divide an hour evenly."""
    if step_minutes <= 0 or 60 % step_minutes:
        raise ValueError(f"bad step: {step_minutes}")

def _round_clock(minutes: int, step_minutes: int) -> int:
    """Nearest multiple of the step. Halves round up."""
    half = step_minutes // 2
    return (minutes + half) // step_minutes * step_minutes

def _round_span(span: Span, step_minutes: int) -> Span:
    start = _round_clock(span.start, step_minutes)
    end = _round_clock(span.end, step_minutes)
    return Span(start, end)

def _label(span: Span) -> str:
    hours, remainder = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {remainder}m)"

# ---
def label_rounded_spans(
    spans: Iterable[Span], step_minutes: int
) -> List[str]:
    """Round each span to the step and label it."""
    _check_step(step_minutes)
    return [
        _label(_round_span(span, step_minutes))
        for span in spans
    ]
